#!/usr/bin/env python3
"""Create and validate a VTF 7.2 RGBA8888 texture for Counter-Strike: Source."""
import struct
import sys
from pathlib import Path
from PIL import Image

WIDTH = 1024
HEIGHT = 1024
HEADER_SIZE = 80
# CLAMPS | CLAMPT | NOMIP | NOLOD. Alpha flags are generated by VTEX,
# must not be forced (the old 0x230C set ONEBITALPHA and EIGHTBITALPHA together).
TEXTURE_FLAGS = 0x0000030C

if len(sys.argv) != 3:
    raise SystemExit("usage: build_vtf.py input.jpg output.vtf")

src = Path(sys.argv[1])
dst = Path(sys.argv[2])
with Image.open(src) as source:
    image = source.convert("RGBA").resize((WIDTH, HEIGHT), Image.Resampling.LANCZOS)
pixels = image.tobytes()

header = bytearray(HEADER_SIZE)
header[0:4] = b"VTF\x00"
struct.pack_into("<II", header, 4, 7, 2)
struct.pack_into("<I", header, 12, HEADER_SIZE)
struct.pack_into("<HH", header, 16, WIDTH, HEIGHT)
struct.pack_into("<I", header, 20, TEXTURE_FLAGS)
struct.pack_into("<HH", header, 24, 1, 0)
# VTF 7.2 reflectivity and alignment padding are zero-initialized.
struct.pack_into("<fff", header, 32, 0.0, 0.0, 0.0)
struct.pack_into("<f", header, 48, 1.0)
struct.pack_into("<I", header, 52, 0)  # IMAGE_FORMAT_RGBA8888
header[56] = 1                        # one mip level
struct.pack_into("<i", header, 57, -1)  # IMAGE_FORMAT_NONE: no thumbnail
header[61] = 0
header[62] = 0
struct.pack_into("<H", header, 63, 1)  # 2D texture depth

dst.parent.mkdir(parents=True, exist_ok=True)
dst.write_bytes(header + pixels)

# Read-back validation: catch malformed offsets, dimensions, format and size.
data = dst.read_bytes()
if data[:4] != b"VTF\x00":
    raise SystemExit("VTF signature validation failed")
major, minor = struct.unpack_from("<II", data, 4)
header_size = struct.unpack_from("<I", data, 12)[0]
width, height = struct.unpack_from("<HH", data, 16)
flags = struct.unpack_from("<I", data, 20)[0]
frames = struct.unpack_from("<H", data, 24)[0]
image_format = struct.unpack_from("<I", data, 52)[0]
mip_count = data[56]
lowres_format = struct.unpack_from("<i", data, 57)[0]
depth = struct.unpack_from("<H", data, 63)[0]
expected_size = HEADER_SIZE + WIDTH * HEIGHT * 4
if (major, minor, header_size, width, height, flags, frames, image_format, mip_count, lowres_format, depth, len(data)) != (7, 2, HEADER_SIZE, WIDTH, HEIGHT, TEXTURE_FLAGS, 1, 0, 1, -1, 1, expected_size):
    raise SystemExit("VTF header or payload validation failed")
print(f"Validated {dst}: VTF {major}.{minor}, {width}x{height}, RGBA8888, flags=0x{flags:08X}, bytes={len(data)}")
